sp_widget.client_script:
function($scope, spUtil) {
  var c = this;

  c.searchQuery = '';
  c.sortField = 'name';
  c.sortAsc   = true;

  c.showWorksiteModal = false;
  c.showAddModal      = false;
  c.showVerifyModal   = false;
  c.showNoDrModal     = false;
  c.editEmp           = {};
  c.newEmp            = {};
  c.verifyEmp         = {};
  c.userPicker        = {};
  c.working           = false;

  c.worksitePickerOpen = false;
  c.addPickerOpen      = false;
  c.worksiteSearch     = '';
  c.addSearch          = '';

  c.states = [
    { code: 'AL', name: 'Alabama' },
    { code: 'AK', name: 'Alaska' },
    { code: 'AZ', name: 'Arizona' },
    { code: 'AR', name: 'Arkansas' },
    { code: 'CA', name: 'California' },
    { code: 'CO', name: 'Colorado' },
    { code: 'CT', name: 'Connecticut' },
    { code: 'DE', name: 'Delaware' },
    { code: 'DC', name: 'District of Columbia' },
    { code: 'FL', name: 'Florida' },
    { code: 'GA', name: 'Georgia' },
    { code: 'HI', name: 'Hawaii' },
    { code: 'ID', name: 'Idaho' },
    { code: 'IL', name: 'Illinois' },
    { code: 'IN', name: 'Indiana' },
    { code: 'IA', name: 'Iowa' },
    { code: 'KS', name: 'Kansas' },
    { code: 'KY', name: 'Kentucky' },
    { code: 'LA', name: 'Louisiana' },
    { code: 'ME', name: 'Maine' },
    { code: 'MD', name: 'Maryland' },
    { code: 'MA', name: 'Massachusetts' },
    { code: 'MI', name: 'Michigan' },
    { code: 'MN', name: 'Minnesota' },
    { code: 'MS', name: 'Mississippi' },
    { code: 'MO', name: 'Missouri' },
    { code: 'MT', name: 'Montana' },
    { code: 'NE', name: 'Nebraska' },
    { code: 'NV', name: 'Nevada' },
    { code: 'NH', name: 'New Hampshire' },
    { code: 'NJ', name: 'New Jersey' },
    { code: 'NM', name: 'New Mexico' },
    { code: 'NY', name: 'New York' },
    { code: 'NC', name: 'North Carolina' },
    { code: 'ND', name: 'North Dakota' },
    { code: 'OH', name: 'Ohio' },
    { code: 'OK', name: 'Oklahoma' },
    { code: 'OR', name: 'Oregon' },
    { code: 'PA', name: 'Pennsylvania' },
    { code: 'RI', name: 'Rhode Island' },
    { code: 'SC', name: 'South Carolina' },
    { code: 'SD', name: 'South Dakota' },
    { code: 'TN', name: 'Tennessee' },
    { code: 'TX', name: 'Texas' },
    { code: 'UT', name: 'Utah' },
    { code: 'VT', name: 'Vermont' },
    { code: 'VA', name: 'Virginia' },
    { code: 'WA', name: 'Washington' },
    { code: 'WV', name: 'West Virginia' },
    { code: 'WI', name: 'Wisconsin' },
    { code: 'WY', name: 'Wyoming' },
    { code: 'AS', name: 'American Samoa' },
    { code: 'FM', name: 'Federated States of Micronesia' },
    { code: 'GU', name: 'Guam' },
    { code: 'MH', name: 'Marshall Islands' },
    { code: 'MP', name: 'Northern Mariana Islands' },
    { code: 'PW', name: 'Palau' },
    { code: 'PR', name: 'Puerto Rico' },
    { code: 'VI', name: 'U.S. Virgin Islands' },
    { code: 'AA', name: 'Armed Forces Americas' },
    { code: 'AE', name: 'Armed Forces Europe' },
    { code: 'AP', name: 'Armed Forces Pacific' }
  ];

  c.sortBy = function(field) {
    if (c.sortField === field) {
      c.sortAsc = !c.sortAsc;
    } else {
      c.sortField = field;
      c.sortAsc   = true;
    }
  };

  c.filtered = function() {
    var q = (c.searchQuery || '').toLowerCase().trim();
    var list = c.data.employees || [];
    if (q) {
      list = list.filter(function(emp) {
        return (emp.name             || '').toLowerCase().indexOf(q) > -1 ||
               (emp.title            || '').toLowerCase().indexOf(q) > -1 ||
               (emp.department       || '').toLowerCase().indexOf(q) > -1 ||
               (emp.worksite_display || '').toLowerCase().indexOf(q) > -1 ||
               (emp.email            || '').toLowerCase().indexOf(q) > -1;
      });
    }
    var field = c.sortField;
    var asc   = c.sortAsc;
    list = list.slice().sort(function(a, b) {
      var av = (a[field] || '').toLowerCase();
      var bv = (b[field] || '').toLowerCase();
      if (av < bv) return asc ? -1 :  1;
      if (av > bv) return asc ?  1 : -1;
      return 0;
    });
    return list;
  };

  c.initials = function(name) {
    if (!name) return '?';
    var parts = name.trim().split(/\s+/);
    if (parts.length === 1) return parts[0].charAt(0).toUpperCase();
    return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
  };

  // ── Worksite address picker ────────────────────────────────
  // Populates address fields and clears cubicle/suite/floor.
  // The location sys_id is never sent to the server.
  c.pickLocation = function(emp, loc) {
    emp.street_1       = loc.street_1;
    emp.street_2       = loc.street_2;
    emp.city           = loc.city;
    emp.state          = loc.state;
    emp.zip            = loc.zip;
    emp.location_label = loc.label;
    emp.cubicle        = '';
    emp.suite          = '';
    emp.floor          = '';
  };

  c.filteredLocations = function(term) {
    var q = (term || '').toLowerCase().trim();
    if (!q) return [];
    var results = [];
    var list = c.data.locations || [];
    for (var i = 0; i < list.length; i++) {
      if ((list[i].label || '').toLowerCase().indexOf(q) > -1) {
        results.push(list[i]);
        if (results.length >= 10) break;
      }
    }
    return results;
  };

  // ── Remote toggle ──────────────────────────────────────────
  // Check:   clear + lock cubicle/suite/floor; set streets to "Remote" (read-only);
  //          clear city/state/zip
  // Uncheck: restore cubicle/suite/floor; clear streets
  c.onRemoteToggle = function(emp) {
    if (emp.remote) {
      emp._remoteSavedCubicle = emp.cubicle;
      emp._remoteSavedSuite   = emp.suite;
      emp._remoteSavedFloor   = emp.floor;
      emp.cubicle  = '';
      emp.suite    = '';
      emp.floor    = '';
      emp.street_1 = 'Remote Worker';
      emp.street_2 = 'Remote Worker';
      emp.city     = '';
      emp.state    = '';
      emp.zip      = '';
    }  else {
      emp.cubicle  = emp._remoteSavedCubicle || '';
      emp.suite    = emp._remoteSavedSuite   || '';
      emp.floor    = emp._remoteSavedFloor   || '';
      emp.street_1 = '';
      emp.street_2 = '';
      emp.city     = '';
      emp.state    = '';
      emp.zip      = '';
    }
  };

  // ── Validation ─────────────────────────────────────────────
  c.validateAddress = function(emp) {
    if (emp.remote) {
      if (!emp.city || !emp.state || !emp.zip) {
        return 'In Remote mode, please fill in City, State, and ZIP.';
      }
    }
    return '';
  };

  // ── Change Worksite modal ──────────────────────────────────
  c.openWorksite = function(emp) {
    c.editEmp                = angular.copy(emp);
    c.editEmp.location_label = '';   // picker always starts blank
    c.worksitePickerOpen     = false;
    c.worksiteSearch         = '';
    c.showWorksiteModal      = true;
  };

  c.closeWorksite = function() {
    c.showWorksiteModal = false;
    c.editEmp           = {};
  };

  c.submitWorksite = function() {
    var e = c.editEmp || {};
    var missing = [];
    if (!(e.street_1 || '').trim()) missing.push('Street 1');
    if (!(e.city     || '').trim()) missing.push('City');
    if (!(e.state    || '').trim()) missing.push('State');
    if (!(e.zip      || '').trim()) missing.push('ZIP');
    if (missing.length) {
      alert('Please fill in the following required field(s): ' + missing.join(', ') + '.');
      return;
    }
    if (!/^\d{5}$/.test((e.zip || '').trim())) {
      alert('ZIP must be exactly 5 digits.');
      return;
    }
    var msg = c.validateAddress(c.editEmp);
    if (msg) { alert(msg); return; }
    if (c.working) return;
    c.working = true;
    c.server.get({ action: 'updateWorksite', emp: c.editEmp }).then(function(r) {
      c.working           = false;
      c.showWorksiteModal = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage((res.name || 'Employee') + "'s worksite has been updated.");
      } else if (res) {
        spUtil.addErrorMessage('Could not update worksite: ' + (res.message || 'unknown error'));
      }
      c.editEmp = {};
    });
  };

  // ── Remove ─────────────────────────────────────────────────
  c.removeEmployee = function(emp) {
    if (!confirm('Remove ' + emp.name + ' from your direct reports?')) return;
    if (c.working) return;
    c.working = true;
    c.server.get({ action: 'remove', sys_id: emp.sys_id }).then(function(r) {
      c.working = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      c.syncNoDrFlag(r);
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage(emp.name + ' has been removed from My Direct Reports.');
      } else if (res) {
        spUtil.addErrorMessage('Could not start removal: ' + (res.message || 'unknown error'));
      }
    });
  };

  // ── Verify ─────────────────────────────────────────────────
  c.openVerify = function(emp) {
    if (!emp.verification_required) return;
    c.verifyEmp       = angular.copy(emp);
    c.showVerifyModal = true;
  };

  c.closeVerify = function() {
    c.showVerifyModal = false;
    c.verifyEmp        = {};
  };

  // Tooltip text for the Verify button, based on whether verification is required
  c.verifyTooltip = function(emp) {
    if (emp.verification_required) {
      return 'Click the Verify button to confirm the worksite information for this employee';
    }
    return "Verification of this employee's worksite is not required at this time.";
  };

  // The Verify modal cannot be confirmed until Street 1, City, State and ZIP
  // are all filled in. "NO DATA AVAILABLE" is an accepted Street 1 value.
  c.verifyIncomplete = function() {
    var e  = c.verifyEmp || {};
    if (!(e.street_1 || '').trim()) return true;
    if (!(e.city  || '').trim()) return true;
    if (!(e.state || '').trim()) return true;
    if (!(e.zip   || '').trim()) return true;
    return false;
  };

  c.confirmVerify = function() {
    if (c.verifyIncomplete()) return;
    if (c.working) return;
    c.working = true;
    c.server.get({ action: 'verify', sys_id: c.verifyEmp.sys_id }).then(function(r) {
      c.working = false;
      c.showVerifyModal = false;
      c.verifyEmp        = {};
      if (r.data.employees) { c.data.employees = r.data.employees; }
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage((res.name || 'Employee') + "'s worksite has been verified.");
      } else if (res) {
        spUtil.addErrorMessage('Could not verify worksite: ' + (res.message || 'unknown error'));
      }
    });
  };

  // Jump from the Verify modal straight into the Change Worksite modal
  // for the same employee.
  c.changeWorksiteFromVerify = function() {
    var emp = angular.copy(c.verifyEmp);
    c.showVerifyModal = false;
    c.verifyEmp       = {};
    c.openWorksite(emp);
  };

  // ── Verify No Direct Reports modal ─────────────────────────
  c.openNoDr = function() {
    c.showNoDrModal = true;
  };

  c.closeNoDr = function() {
    c.showNoDrModal = false;
  };

  // Keeps the header's "Verify No Direct Reports" button in sync with the
  // server after any action that can change the flag or the report list.
  c.syncNoDrFlag = function(r) {
    if (r && r.data && angular.isDefined(r.data.no_direct_reports_verification_required)) {
      c.data.no_direct_reports_verification_required = r.data.no_direct_reports_verification_required;
    }
  };

  c.confirmNoDr = function() {
    if (c.working) return;
    c.working = true;
    c.server.get({ action: 'verifyNoDirectReports' }).then(function(r) {
      c.working       = false;
      c.showNoDrModal = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      c.syncNoDrFlag(r);
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage('Thank you. You have confirmed that you have no direct reports.');
      } else if (res) {
        spUtil.addErrorMessage('Could not record confirmation: ' + (res.message || 'unknown error'));
      }
    });
  };

  // ── Add Employee modal ─────────────────────────────────────
  c.openAdd = function() {
    c.newEmp        = { remote: false, location_label: '' };
    c.userPicker    = {};
    c.addPickerOpen = false;
    c.addSearch     = '';
    c.showAddModal  = true;
  };

  c.closeAdd = function() {
    c.showAddModal = false;
    c.newEmp       = {};
    c.userPicker   = {};
  };

  c.submitAdd = function() {
    var userId = c.userPicker && c.userPicker.value;
    var missing = [];
    if (!userId)              missing.push('Employee');
    if (!c.newEmp.street_1)   missing.push('Street 1');
    if (!c.newEmp.city)       missing.push('City');
    if (!c.newEmp.state)      missing.push('State');
    if (!c.newEmp.zip)        missing.push('ZIP');
    if (missing.length) {
      alert('Please fill in the following required field(s): ' + missing.join(', ') + '.');
      return;
    }
    var msg = c.validateAddress(c.newEmp);
    if (msg) { alert(msg); return; }
    if (c.working) return;
    c.working = true;
    var payload    = angular.copy(c.newEmp || {});
    payload.sys_id = userId;
    c.server.get({ action: 'addEmployee', emp: payload }).then(function(r) {
      c.working      = false;
      c.showAddModal = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      c.syncNoDrFlag(r);
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage((res.name || 'Employee') + ' has been added.');
      } else if (res) {
        spUtil.addErrorMessage('Could not add employee: ' + (res.message || 'unknown error'));
      }
      c.newEmp     = {};
      c.userPicker = {};
    });
  };

  // ── Auto-populate worksite fields from the selected sys_user ─
  // Fetches the chosen user's stored worksite values and copies
  // them into the Add Employee form (remote, cubicle/suite/floor,
  // street 1/2, city, state, zip).
  c.loadUserWorksite = function(userId) {
    c.server.get({ action: 'getUser', sys_id: userId }).then(function(r) {
      var u = r.data && r.data.pickedUser;
      if (!u) return;
      c.newEmp.remote         = !!u.remote;
      c.newEmp.cubicle        = u.cubicle  || '';
      c.newEmp.suite          = u.suite    || '';
      c.newEmp.floor          = u.floor    || '';
      c.newEmp.street_1       = u.street_1 || '';
      c.newEmp.street_2       = u.street_2 || '';
      c.newEmp.city           = u.city     || '';
      c.newEmp.state          = u.state    || '';
      c.newEmp.zip            = u.zip      || '';
      c.newEmp.location_label = '';
      // keep the Remote toggle's restore buffer in sync
      c.newEmp._remoteSavedCubicle = u.cubicle || '';
      c.newEmp._remoteSavedSuite   = u.suite   || '';
      c.newEmp._remoteSavedFloor   = u.floor   || '';
    });
  };

  // When an employee is picked in the Add Employee modal, pull their record.
  $scope.$watch(function() {
    return c.userPicker && c.userPicker.value;
  }, function(newVal, oldVal) {
    if (c.showAddModal && newVal && newVal !== oldVal) {
      c.loadUserWorksite(newVal);
    }
  });
}

sp_widget.css:
.ew-modal-body .row {
  padding-left: 0;
  padding-right: 0;
  margin-left: -8px;
  margin-right: -8px;
}
.ew-modal-body .row > [class*="col-"] {
  padding-left: 8px;
  padding-right: 8px;
  box-sizing: border-box;
}
.row.info-row:hover { background-color: #f0f0f0;}
.container { display: inline; }
.row.info-row > div { min-height: 0; padding-top: 0; padding-left: 0; padding-right: 0;}
.hide-element { visibility: hidden; }
.row { padding-left: 1.2rem; }
#dr_staff { padding-top: 0.6rem; padding-bottom: 0.6rem; }
.row.info-row { margin-left: 0; margin-right: 0; padding-left: 0; padding-right: 1rem; }
.avatar-group {
  display: inline-block;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  color: #1B4792;
  vertical-align: middle;
}

.panel-heading {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.ew-head-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
}

.dr-update-btn {
  font-size: 0.85em;
  color: #1B4792;
  text-decoration: none;
  margin-top: 4px;
}
.dr-update-btn:hover { text-decoration: underline; }

.ew-head-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.dr-row-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-left: 2.2rem;
  padding-right: 2.4rem;
  padding-top: 6px;
  padding-bottom: 6px;
}

.dr-avatar-wrap {
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.dr-info { line-height: 1.2; flex: 1 1 auto; }
.dr-name { font-size: 0.85em; margin: 0; }
.dr-detail { font-size: 0.85em; color: #666; margin: 0; }
.dr-info > div + div { margin-top: 1px; }

.dr-actions {
  flex-shrink: 0;
  display: flex;
  gap: 8px;
  align-items: center;
}

.ew-verify-date {
  white-space: nowrap;
  margin-left: 2px;
}

.dr-actions .btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── Inline modal ─────────────────────────────────────────── */
.ew-modal-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1050;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px 16px;
  overflow: auto;
}
.ew-modal {
  background: #fff;
  border-radius: 4px;
  width: 100%;
  max-width: 680px;
  box-shadow: 0 5px 15px rgba(0,0,0,0.5);
  box-sizing: border-box;
  overflow-x: hidden;
}
.ew-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  border-bottom: 1px solid #e5e5e5;
}
.ew-modal-header h4 { margin: 0; font-size: 1.05em; }
.ew-modal-close {
  border: none;
  background: none;
  font-size: 1.6em;
  line-height: 1;
  cursor: pointer;
  color: #888;
}
.ew-modal-close:hover { color: #333; }
.ew-modal-body {
  padding: 12px 16px 8px;
}
.ew-modal-body .form-group {
  margin-bottom: 8px;
}
.ew-modal-body label {
  margin-bottom: 2px;
}
.ew-modal-footer {
  padding: 8px 16px;
  border-top: 1px solid #e5e5e5;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* ── Custom worksite-address picker ───────────────────────── */
.ew-picker { position: relative; }
.ew-picker-control {
  border: 1px solid #ccc;
  border-radius: 4px;
  padding: 6px 10px;
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #fff;
  cursor: pointer;
}
.ew-picker-control:hover { border-color: #999; }
.ew-picker-disabled,
.ew-picker-disabled:hover {
  background: #f0f0f0;
  cursor: not-allowed;
  border-color: #ccc;
  opacity: 0.75;
}
.ew-picker-placeholder { color: #999; }
.ew-picker-panel {
  border: 1px solid #ccc;
  border-radius: 4px;
  margin-top: 4px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.12);
  overflow: hidden;
}
.ew-picker-search {
  border: none;
  border-bottom: 1px solid #eee;
  border-radius: 0;
  box-shadow: none;
}
.ew-picker-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 200px;
  overflow-y: auto;
}
.ew-picker-list li {
  padding: 8px 10px;
  cursor: pointer;
  font-size: 0.9em;
  border-bottom: 1px solid #f3f3f3;
}
.ew-picker-list li:hover { background: #f0f0f0; }
.ew-picker-empty { color: #999; cursor: default; }
.ew-picker-empty:hover { background: #fff; }

/* Read-only worksite fields (when an address is chosen from the list) */
.ew-readonly,
.ew-modal-body input[readonly] {
  background: #f0f0f0;
  cursor: not-allowed;
}
.ew-checkbox { margin: 2px 0 4px; }
.ew-checkbox label { font-weight: normal; cursor: pointer; }
.ew-checkbox-row { display: flex; gap: 24px; margin: 2px 0 6px; }
.ew-checkbox-row .ew-checkbox { margin: 0; }

sp_widget.script:
(function() {

    // ── 0. Supervisory status access check ────────────────────
    var ALLOWED_STATUSES = [
        '74bb71501b1231104da26311f54bcb95',
        'f8bb71501b1231104da26311f54bcb95',
        '38bb71501b1231104da26311f54bcb95'
    ];
    var currentUserGr = new GlideRecord('sys_user');
    if (currentUserGr.get(gs.getUserID())) {
        var userStatus = currentUserGr.getValue('u_supervisory_status') || '';
        if (ALLOWED_STATUSES.indexOf(userStatus) === -1) {
            data.hidden = true;
            return;
        }
    } else {
        data.hidden = true;
        return;
    }

    data.employees = [];
    data.supervisor = '';
    data.error = '';
    data.actionResult = null;
    data.no_direct_reports_verification_required = false;

    var supervisorSysId = options.supervisor_sys_id || $sp.getParameter('supervisor_sys_id') || gs.getUserID();

    if (input && input.action) {
        handleAction(input);
    }

    if (!supervisorSysId) {
        data.error = 'No supervisor specified.';
        return;
    }

    var supGr = new GlideRecord('sys_user');
    if (supGr.get(supervisorSysId)) {
        data.supervisor = supGr.getDisplayValue('name');
        var noDrRaw = supGr.getValue('u_employee_worksite_no_direct_reports_verification_required');
        data.no_direct_reports_verification_required = (noDrRaw === 'true' || noDrRaw === true || noDrRaw == 1);
    } else {
        data.error = 'Supervisor not found.';
        return;
    }

    var empGr = new GlideRecord('sys_user');
    empGr.addActiveQuery();
    empGr.addQuery('u_fpps_supervisor', supervisorSysId);
    empGr.orderBy('last_name');
    empGr.orderBy('first_name');
    empGr.query();
    while (empGr.next()) {
        data.employees.push(buildEmp(empGr));
    }

    // A supervisor with at least one direct report is never asked to verify
    // that they have none.
    if (data.employees.length > 0) {
        data.no_direct_reports_verification_required = false;
    }

    // Locations list for the picker — used only to populate address fields in the modal
    data.locations = [];
    var locGr = new GlideRecord('cmn_location');
    locGr.addQuery('cmn_location_type', 'employee_worksite');
    locGr.orderBy('city');
    locGr.orderBy('u_employee_worksite_street_1');
    locGr.query();
    while (locGr.next()) {
        data.locations.push(buildLoc(locGr));
    }

    // ── Helpers ────────────────────────────────────────────────

    function buildEmp(gr) {
        var cubicle = gr.getValue('u_employee_worksite_cubicle') || '';
        var suite = gr.getValue('u_employee_worksite_suite') || '';
        var floor = gr.getValue('u_employee_worksite_floor') || '';
        var remote = gr.getValue('u_employee_worksite_remote') === 'true' ||
            gr.getValue('u_employee_worksite_remote') === true ||
            gr.getValue('u_employee_worksite_remote') == 1;
        var street1 = gr.getValue('u_employee_worksite_street_1') || '';
        var street2 = gr.getValue('u_employee_worksite_street_2') || '';
        var city = gr.getValue('u_employee_worksite_city') || '';
        var state = gr.getValue('u_employee_worksite_state') || '';
        var zip = gr.getValue('u_employee_worksite_zip') || '';

        var verificationRequired = gr.getValue('u_employee_worksite_verification_required') === 'true' ||
            gr.getValue('u_employee_worksite_verification_required') === true ||
            gr.getValue('u_employee_worksite_verification_required') == 1;

        var lastVerifiedDisplay = '';
        var lastVerifiedRaw = gr.getValue('u_employee_worksite_last_verified');
        if (lastVerifiedRaw) {
            var lvGdt = new GlideDateTime(lastVerifiedRaw);
            lastVerifiedDisplay = lvGdt.getDate().getDisplayValue();
        }

        var line1 = [street1, street2].filter(function(s) {
            return s;
        }).join(', ');
        var line2 = [city, state].filter(function(s) {
            return s;
        }).join(', ');
        if (zip) line2 += (line2 ? ' ' : '') + zip;
        var display = [line1, line2].filter(function(s) {
            return s;
        }).join(', ');

        var locParts = [];
        if (cubicle) locParts.push('Cubicle/Office ' + cubicle);
        if (suite) locParts.push('Suite ' + suite);
        if (floor) locParts.push('Floor ' + floor);
        var locLine = locParts.join(' \u2022 ');

        return {
            sys_id: gr.getUniqueValue(),
            name: gr.getDisplayValue('name'),
            employee_number: gr.getValue('employee_number') || '',
            title: gr.getDisplayValue('title') || '',
            department: gr.getDisplayValue('department') || '',
            email: gr.getValue('email') || '',
            phone: gr.getValue('phone') || '',
            remote: remote,
            cubicle: cubicle,
            suite: suite,
            floor: floor,
            street_1: street1,
            street_2: street2,
            city: city,
            state: state,
            zip: zip,
            loc_line: locLine,
            worksite_display: display,
            worksite: display,
            verification_required: verificationRequired,
            last_verified_display: lastVerifiedDisplay
        };
    }

    function buildLoc(gr) {
        var s1 = gr.getValue('u_employee_worksite_street_1') || '';
        var s2 = gr.getValue('u_employee_worksite_street_2') || '';
        var ci = gr.getValue('city') || '';
        var st = gr.getValue('state') || '';
        var zp = gr.getValue('zip') || '';
        return {
            sys_id: gr.getUniqueValue(),
            street_1: s1,
            street_2: s2,
            city: ci,
            state: st,
            zip: zp,
            label: locLabel(s1, s2, ci, st, zp)
        };
    }

    function locLabel(s1, s2, ci, st, zp) {
        var seg = [];
        if (s1) seg.push(s1);
        if (s2) seg.push(s2);
        if (ci) seg.push(ci);
        var tail = [st, zp].filter(function(x) {
            return x;
        }).join(' ');
        if (tail) seg.push(tail);
        return seg.join(', ');
    }

    function applyWorksite(gr, src) {
        gr.setValue('u_employee_worksite_remote', src.remote ? 'true' : 'false');

        if (src.remote) {
            // Remote: clear cubicle/suite/floor, write "Remote" to both street fields
            gr.setValue('u_employee_worksite_cubicle', '');
            gr.setValue('u_employee_worksite_suite', '');
            gr.setValue('u_employee_worksite_floor', '');
            gr.setValue('u_employee_worksite_street_1', 'Remote Worker');
            gr.setValue('u_employee_worksite_street_2', 'Remote Worker');
            gr.setValue('u_employee_worksite_city', src.city || '');
            gr.setValue('u_employee_worksite_state', src.state || '');
            gr.setValue('u_employee_worksite_zip', src.zip || '');
            return;
        }

        // Non-remote: save all fields as supplied. u_employee_worksite_address is never written.
        gr.setValue('u_employee_worksite_cubicle', src.cubicle || '');
        gr.setValue('u_employee_worksite_suite', src.suite || '');
        gr.setValue('u_employee_worksite_floor', src.floor || '');
        gr.setValue('u_employee_worksite_street_1', src.street_1 || '');
        gr.setValue('u_employee_worksite_street_2', src.street_2 || '');
        gr.setValue('u_employee_worksite_city', src.city || '');
        gr.setValue('u_employee_worksite_state', src.state || '');
        gr.setValue('u_employee_worksite_zip', src.zip || '');
    }

    function validateAddress(src) {
        if (src.remote) {
            if (!src.city || !src.state || !src.zip) {
                return 'In Remote mode, City, State, and ZIP are required.';
            }
        }
        return '';
    }

    function handleAction(inp) {
        var act = inp.action;

        if (act === 'getUser' && inp.sys_id) {
            var gugr = new GlideRecord('sys_user');
            if (gugr.get(inp.sys_id)) {
                data.pickedUser = buildEmp(gugr);
            } else {
                data.pickedUser = null;
            }
            return;
        }

        if (act === 'updateWorksite' && inp.emp && inp.emp.sys_id) {
            var reqMsgU = '';
            if (!inp.emp.street_1)   reqMsgU = 'Street 1 is required.';
            else if (!inp.emp.city)  reqMsgU = 'City is required.';
            else if (!inp.emp.state) reqMsgU = 'State is required.';
            else if (!inp.emp.zip)   reqMsgU = 'ZIP is required.';
            else if (!/^\d{5}$/.test(String(inp.emp.zip))) reqMsgU = 'ZIP must be exactly 5 digits.';
            if (reqMsgU) {
                data.actionResult = {
                    ok: false,
                    type: 'update',
                    message: reqMsgU
                };
                return;
            }
            var vmsgU = validateAddress(inp.emp);
            if (vmsgU) {
                data.actionResult = {
                    ok: false,
                    type: 'update',
                    message: vmsgU
                };
                return;
            }
            var ugr = new GlideRecord('sys_user');
            if (ugr.get(inp.emp.sys_id)) {
                applyWorksite(ugr, inp.emp);
                ugr.update();
                data.actionResult = {
                    ok: true,
                    type: 'update',
                    name: ugr.getDisplayValue('name')
                };
            } else {
                data.actionResult = {
                    ok: false,
                    type: 'update',
                    message: 'User not found.'
                };
            }
            return;
        }

        if (act === 'remove' && inp.sys_id) {
            var rgr = new GlideRecord('sys_user');
            if (!rgr.get(inp.sys_id)) {
                data.actionResult = {
                    ok: false,
                    type: 'remove',
                    message: 'User not found.'
                };
                return;
            }
            var removeName = rgr.getDisplayValue('name');
            rgr.setValue('u_fpps_supervisor', '');
			rgr.setValue('u_fpps_supervisor_eci', '');
            rgr.update();
            data.actionResult = {
                ok: true,
                type: 'remove',
                name: removeName
            };
            return;
        }

        if (act === 'verify' && inp.sys_id) {
            var vgr = new GlideRecord('sys_user');
            if (!vgr.get(inp.sys_id)) {
                data.actionResult = {
                    ok: false,
                    type: 'verify',
                    message: 'User not found.'
                };
                return;
            }
            vgr.setValue('u_employee_worksite_last_verified', new GlideDateTime());
            vgr.setValue('u_employee_worksite_last_verified_by', gs.getUserID());
            vgr.setValue('u_employee_worksite_verification_required', false);
            vgr.update();
            data.actionResult = {
                ok: true,
                type: 'verify',
                name: vgr.getDisplayValue('name')
            };
            return;
        }

        if (act === 'verifyNoDirectReports') {
            var ndgr = new GlideRecord('sys_user');
            if (!ndgr.get(supervisorSysId)) {
                data.actionResult = {
                    ok: false,
                    type: 'verifyNoDirectReports',
                    message: 'User not found.'
                };
                return;
            }
            ndgr.setValue('u_employee_worksite_no_direct_reports_verification_required', false);
            ndgr.update();
            data.actionResult = {
                ok: true,
                type: 'verifyNoDirectReports',
                name: ndgr.getDisplayValue('name')
            };
            return;
        }

        if (act === 'addEmployee' && inp.emp && inp.emp.sys_id) {
            var reqMsgA = '';
            if (!inp.emp.street_1)      reqMsgA = 'Street 1 is required.';
            else if (!inp.emp.city)     reqMsgA = 'City is required.';
            else if (!inp.emp.state)    reqMsgA = 'State is required.';
            else if (!inp.emp.zip)      reqMsgA = 'ZIP is required.';
            if (reqMsgA) {
                data.actionResult = {
                    ok: false,
                    type: 'add',
                    message: reqMsgA
                };
                return;
            }
            var vmsgA = validateAddress(inp.emp);
            if (vmsgA) {
                data.actionResult = {
                    ok: false,
                    type: 'add',
                    message: vmsgA
                };
                return;
            }
            var agr = new GlideRecord('sys_user');
            if (!agr.get(inp.emp.sys_id)) {
                data.actionResult = {
                    ok: false,
                    type: 'add',
                    message: 'User not found.'
                };
                return;
            }
            applyWorksite(agr, inp.emp);
            agr.setValue('u_fpps_supervisor', supervisorSysId);
            agr.update();
            // The supervisor now has a direct report, so the
            // "no direct reports" verification no longer applies.
            var addSupGr = new GlideRecord('sys_user');
            if (addSupGr.get(supervisorSysId)) {
                addSupGr.setValue('u_employee_worksite_no_direct_reports_verification_required', false);
                addSupGr.update();
            }
            data.actionResult = {
                ok: true,
                type: 'add',
                name: agr.getDisplayValue('name')
            };
            return;
        }
    }

})();

sp_widget.client_script:
function($scope, spUtil) {
  var c = this;

  // Search query binding
  c.searchQuery = '';

  // Sorting state
  c.sortField = 'name';
  c.sortAsc   = true;

  // Modal / action state
  c.showWorksiteModal = false;
  c.showAddModal      = false;
  c.editEmp           = {};   // working copy of the employee being edited
  c.newEmp            = {};   // worksite fields for the employee being added
  c.userPicker        = {};   // sn-record-picker model: { value, displayValue }
  c.working           = false;

  // Custom worksite-address picker state (one set per modal)
  c.worksitePickerOpen = false;
  c.addPickerOpen      = false;
  c.worksiteSearch     = '';
  c.addSearch          = '';

  // State / territory / military codes (USPS) for the worksite State dropdown.
  c.states = [
    { code: 'AL', name: 'Alabama' },
    { code: 'AK', name: 'Alaska' },
    { code: 'AZ', name: 'Arizona' },
    { code: 'AR', name: 'Arkansas' },
    { code: 'CA', name: 'California' },
    { code: 'CO', name: 'Colorado' },
    { code: 'CT', name: 'Connecticut' },
    { code: 'DE', name: 'Delaware' },
    { code: 'DC', name: 'District of Columbia' },
    { code: 'FL', name: 'Florida' },
    { code: 'GA', name: 'Georgia' },
    { code: 'HI', name: 'Hawaii' },
    { code: 'ID', name: 'Idaho' },
    { code: 'IL', name: 'Illinois' },
    { code: 'IN', name: 'Indiana' },
    { code: 'IA', name: 'Iowa' },
    { code: 'KS', name: 'Kansas' },
    { code: 'KY', name: 'Kentucky' },
    { code: 'LA', name: 'Louisiana' },
    { code: 'ME', name: 'Maine' },
    { code: 'MD', name: 'Maryland' },
    { code: 'MA', name: 'Massachusetts' },
    { code: 'MI', name: 'Michigan' },
    { code: 'MN', name: 'Minnesota' },
    { code: 'MS', name: 'Mississippi' },
    { code: 'MO', name: 'Missouri' },
    { code: 'MT', name: 'Montana' },
    { code: 'NE', name: 'Nebraska' },
    { code: 'NV', name: 'Nevada' },
    { code: 'NH', name: 'New Hampshire' },
    { code: 'NJ', name: 'New Jersey' },
    { code: 'NM', name: 'New Mexico' },
    { code: 'NY', name: 'New York' },
    { code: 'NC', name: 'North Carolina' },
    { code: 'ND', name: 'North Dakota' },
    { code: 'OH', name: 'Ohio' },
    { code: 'OK', name: 'Oklahoma' },
    { code: 'OR', name: 'Oregon' },
    { code: 'PA', name: 'Pennsylvania' },
    { code: 'RI', name: 'Rhode Island' },
    { code: 'SC', name: 'South Carolina' },
    { code: 'SD', name: 'South Dakota' },
    { code: 'TN', name: 'Tennessee' },
    { code: 'TX', name: 'Texas' },
    { code: 'UT', name: 'Utah' },
    { code: 'VT', name: 'Vermont' },
    { code: 'VA', name: 'Virginia' },
    { code: 'WA', name: 'Washington' },
    { code: 'WV', name: 'West Virginia' },
    { code: 'WI', name: 'Wisconsin' },
    { code: 'WY', name: 'Wyoming' },
    // Territories & freely associated states
    { code: 'AS', name: 'American Samoa' },
    { code: 'FM', name: 'Federated States of Micronesia' },
    { code: 'GU', name: 'Guam' },
    { code: 'MH', name: 'Marshall Islands' },
    { code: 'MP', name: 'Northern Mariana Islands' },
    { code: 'PW', name: 'Palau' },
    { code: 'PR', name: 'Puerto Rico' },
    { code: 'VI', name: 'U.S. Virgin Islands' },
    // Military (APO/FPO/DPO)
    { code: 'AA', name: 'Armed Forces Americas' },
    { code: 'AE', name: 'Armed Forces Europe' },
    { code: 'AP', name: 'Armed Forces Pacific' }
  ];

  /**
   * Toggle sort column; flip direction if same column clicked.
   */
  c.sortBy = function(field) {
    if (c.sortField === field) {
      c.sortAsc = !c.sortAsc;
    } else {
      c.sortField = field;
      c.sortAsc   = true;
    }
  };

  /**
   * Returns filtered + sorted employee list.
   */
  c.filtered = function() {
    var q = (c.searchQuery || '').toLowerCase().trim();
    var list = c.data.employees || [];

    if (q) {
      list = list.filter(function(emp) {
        return (emp.name             || '').toLowerCase().indexOf(q) > -1 ||
               (emp.title            || '').toLowerCase().indexOf(q) > -1 ||
               (emp.department       || '').toLowerCase().indexOf(q) > -1 ||
               (emp.worksite_display || '').toLowerCase().indexOf(q) > -1 ||
               (emp.email            || '').toLowerCase().indexOf(q) > -1;
      });
    }

    // Sort
    var field = c.sortField;
    var asc   = c.sortAsc;
    list = list.slice().sort(function(a, b) {
      var av = (a[field] || '').toLowerCase();
      var bv = (b[field] || '').toLowerCase();
      if (av < bv) return asc ? -1 :  1;
      if (av > bv) return asc ?  1 : -1;
      return 0;
    });

    return list;
  };

  /**
   * Generate initials from a display name (up to 2 chars).
   */
  c.initials = function(name) {
    if (!name) return '?';
    var parts = name.trim().split(/\s+/);
    if (parts.length === 1) return parts[0].charAt(0).toUpperCase();
    return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
  };

  // ───────────────────────────────────────────────────────────
  //  Worksite address picker
  // ───────────────────────────────────────────────────────────
  // Select a standardized cmn_location address: store the reference and
  // copy its values into the (read-only) address fields.
  c.pickLocation = function(emp, loc) {
    emp.location       = loc.sys_id;
    emp.location_label = loc.label;
    emp.street_1       = loc.street_1;
    emp.street_2       = loc.street_2;
    emp.city           = loc.city;
    emp.state          = loc.state;
    emp.zip            = loc.zip;
  };

  c.clearAddressFields = function(emp) {
    emp.street_1 = '';
    emp.street_2 = '';
    emp.city     = '';
    emp.state    = '';
    emp.zip      = '';
  };

  // Returns filtered address options capped at 10.
  // Returns empty array when term is blank so nothing renders until the user types.
  c.filteredLocations = function(term) {
    var q = (term || '').toLowerCase().trim();
    if (!q) return [];
    var results = [];
    var list = c.data.locations || [];
    for (var i = 0; i < list.length; i++) {
      if ((list[i].label || '').toLowerCase().indexOf(q) > -1) {
        results.push(list[i]);
        if (results.length >= 10) break;
      }
    }
    return results;
  };

  // Fired when the "Address not in list" checkbox changes.
  c.onManualToggle = function(emp) {
    if (emp.manual) {
      // Entering manual mode: remember the current list selection so it can
      // be restored if the user switches back, then drop the reference.
      emp._savedLocation = emp.location;
      emp._savedLabel    = emp.location_label;
      emp._savedAddress  = {
        street_1: emp.street_1,
        street_2: emp.street_2,
        city:     emp.city,
        state:    emp.state,
        zip:      emp.zip
      };
      emp.location       = '';
      emp.location_label = '';
      c.worksitePickerOpen = false;
      c.addPickerOpen      = false;
    } else if (emp._savedLocation) {
      // Returning to list mode: restore the previously selected address.
      emp.location       = emp._savedLocation;
      emp.location_label = emp._savedLabel;
      emp.street_1       = emp._savedAddress.street_1;
      emp.street_2       = emp._savedAddress.street_2;
      emp.city           = emp._savedAddress.city;
      emp.state          = emp._savedAddress.state;
      emp.zip            = emp._savedAddress.zip;
    } else {
      // Nothing was selected before: clear the typed values.
      c.clearAddressFields(emp);
    }
  };

  // Fired when the "Remote" checkbox changes.
  c.onRemoteToggle = function(emp) {
    if (emp.remote) {
      // Entering remote mode: snapshot the full address state so the picker
      // selection (if any) can be fully restored on uncheck.
      emp._remoteSavedLocation = emp.location;
      emp._remoteSavedLabel    = emp.location_label;
      emp._remoteSavedManual   = emp.manual;
      emp._remoteSavedAddress  = {
        street_1: emp.street_1,
        street_2: emp.street_2,
        city:     emp.city,
        state:    emp.state,
        zip:      emp.zip
      };
      emp.location       = '';
      emp.location_label = '';
      emp.manual         = false;
      emp.street_1       = 'Remote';
      emp.street_2       = 'Remote';
      emp.city           = '';
      emp.state          = '';
      emp.zip            = '';
      c.worksitePickerOpen = false;
      c.addPickerOpen      = false;
    } else {
      emp.manual = emp._remoteSavedManual || false;
      if (emp._remoteSavedLocation) {
        // There was a picker selection — restore it fully including city/state/zip.
        emp.location       = emp._remoteSavedLocation;
        emp.location_label = emp._remoteSavedLabel;
        emp.street_1       = emp._remoteSavedAddress.street_1;
        emp.street_2       = emp._remoteSavedAddress.street_2;
        emp.city           = emp._remoteSavedAddress.city;
        emp.state          = emp._remoteSavedAddress.state;
        emp.zip            = emp._remoteSavedAddress.zip;
      } else {
        // No prior picker selection — clear all address fields.
        emp.location       = '';
        emp.location_label = '';
        emp.street_1       = '';
        emp.street_2       = '';
        emp.city           = '';
        emp.state          = '';
        emp.zip            = '';
      }
    }
  };

  // Returns an error message, or '' if the address portion is valid.
  c.validateAddress = function(emp) {
    if (emp.remote) {
      // Remote mode: only city, state, zip are required.
      if (!emp.city || !emp.state || !emp.zip) {
        return 'In Remote mode, please fill in City, State, and ZIP.';
      }
      return '';
    }
    if (emp.manual) {
      if (!emp.street_1 || !emp.city || !emp.state || !emp.zip) {
        return 'Please fill in Street 1, City, State, and ZIP (Street 2 is optional).';
      }
      return '';
    }
    if (!emp.location) {
      return 'Please select an address, or check "Address not in list".';
    }
    return '';
  };

  // ───────────────────────────────────────────────────────────
  //  Change Worksite
  // ───────────────────────────────────────────────────────────
  c.openWorksite = function(emp) {
    c.editEmp            = angular.copy(emp);
    c.worksitePickerOpen = false;
    c.worksiteSearch     = '';
    c.showWorksiteModal  = true;
  };

  c.closeWorksite = function() {
    c.showWorksiteModal = false;
    c.editEmp           = {};
  };

  c.submitWorksite = function() {
    var msg = c.validateAddress(c.editEmp);
    if (msg) { alert(msg); return; }
    if (c.working) return;
    c.working = true;
    c.server.get({ action: 'updateWorksite', emp: c.editEmp }).then(function(r) {
      c.working           = false;
      c.showWorksiteModal = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage((res.name || 'Employee') + "'s worksite has been updated.");
      } else if (res) {
        spUtil.addErrorMessage('Could not update worksite: ' + (res.message || 'unknown error'));
      }
      c.editEmp = {};
    });
  };

  // ───────────────────────────────────────────────────────────
  //  Remove (detaches the employee from this supervisor)
  // ───────────────────────────────────────────────────────────
  c.removeEmployee = function(emp) {
    if (!confirm('Remove ' + emp.name + ' from your direct reports?')) return;
    if (c.working) return;
    c.working = true;
    c.server.get({ action: 'remove', sys_id: emp.sys_id }).then(function(r) {
      c.working = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage(emp.name + ' has been removed from My Direct Reports.');
      } else if (res) {
        spUtil.addErrorMessage('Could not start removal: ' + (res.message || 'unknown error'));
      }
    });
  };

  // ───────────────────────────────────────────────────────────
  //  Add employee (sets worksite + attaches to this supervisor)
  // ───────────────────────────────────────────────────────────
  c.openAdd = function() {
    c.newEmp        = { manual: false, remote: false, location: '', location_label: '' };
    c.userPicker    = {};
    c.addPickerOpen = false;
    c.addSearch     = '';
    c.showAddModal  = true;
  };

  c.closeAdd = function() {
    c.showAddModal = false;
    c.newEmp       = {};
    c.userPicker   = {};
  };

  c.submitAdd = function() {
    var userId = c.userPicker && c.userPicker.value;
    if (!userId) {
      alert('Please select an employee.');
      return;
    }
    var msg = c.validateAddress(c.newEmp);
    if (msg) { alert(msg); return; }
    if (c.working) return;
    c.working = true;

    var payload    = angular.copy(c.newEmp || {});
    payload.sys_id = userId;

    c.server.get({ action: 'addEmployee', emp: payload }).then(function(r) {
      c.working      = false;
      c.showAddModal = false;
      if (r.data.employees) { c.data.employees = r.data.employees; }
      var res = r.data.actionResult;
      if (res && res.ok) {
        spUtil.addInfoMessage('Thank you for your submissions.  Worksite information for ' + (res.name || 'Employee') + ' will be updated.');
      } else if (res) {
        spUtil.addErrorMessage('Could not add employee: ' + (res.message || 'unknown error'));
      }
      c.newEmp     = {};
      c.userPicker = {};
    });
  };
}

sp_widget.css:
.ew-modal-body .row { padding-left: 0; margin-left: 0; margin-right: 0; }
.row.info-row:hover { background-color: #f0f0f0;}
.container { display: inline; }
.row.info-row &gt; div { min-height: 35px; padding-top: 9px; padding-left: 0; padding-right: 0;}
.hide-element { visibility: hidden; }
.row { padding-left: 1.2rem; }
#dr_staff { padding-top: 2.2rem; padding-bottom: 2.2rem; }
.row.info-row { margin-left: 0; margin-right: 0; padding-left: 0; padding-right: 1rem; }
.avatar-group {
  display: inline-block;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  color: #1B4792;
  vertical-align: middle;
}

.panel-heading {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.ew-head-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
}

.dr-update-btn {
  font-size: 0.85em;
  color: #1B4792;
  text-decoration: none;
  margin-top: 4px;
}
.dr-update-btn:hover { text-decoration: underline; }

.dr-row-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-left: 2.2rem; 
  padding-right: 2.4rem;
}

.dr-avatar-wrap {
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.dr-info { line-height: 1.5; flex: 1 1 auto; }
.dr-name { font-size: 0.85em; }
.dr-detail { font-size: 0.85em; color: #666; }

.dr-actions {
  flex-shrink: 0;
  display: flex;
  gap: 8px;
  align-items: center;
}

/* ── Inline modal ─────────────────────────────────────────── */
.ew-modal-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1050;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px 16px;
  overflow: auto;
}
.ew-modal {
  background: #fff;
  border-radius: 4px;
  width: 100%;
  max-width: 680px;
  box-shadow: 0 5px 15px rgba(0,0,0,0.5);
}
.ew-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  border-bottom: 1px solid #e5e5e5;
}
.ew-modal-header h4 { margin: 0; font-size: 1.05em; }
.ew-modal-close {
  border: none;
  background: none;
  font-size: 1.6em;
  line-height: 1;
  cursor: pointer;
  color: #888;
}
.ew-modal-close:hover { color: #333; }
.ew-modal-body {
  padding: 16px 28px 12px;
}
.ew-modal-body .form-group {
  margin-bottom: 8px;
}
.ew-modal-body label {
  margin-bottom: 2px;
}
.ew-modal-footer {
  padding: 8px 16px;
  border-top: 1px solid #e5e5e5;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* ── Custom worksite-address picker ───────────────────────── */
.ew-picker { position: relative; }
.ew-picker-control {
  border: 1px solid #ccc;
  border-radius: 4px;
  padding: 6px 10px;
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #fff;
  cursor: pointer;
}
.ew-picker-control:hover { border-color: #999; }
.ew-picker-disabled,
.ew-picker-disabled:hover {
  background: #f0f0f0;
  cursor: not-allowed;
  border-color: #ccc;
  opacity: 0.75;
}
.ew-picker-placeholder { color: #999; }
.ew-picker-panel {
  border: 1px solid #ccc;
  border-radius: 4px;
  margin-top: 4px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.12);
  overflow: hidden;
}
.ew-picker-search {
  border: none;
  border-bottom: 1px solid #eee;
  border-radius: 0;
  box-shadow: none;
}
.ew-picker-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 200px;
  overflow-y: auto;
}
.ew-picker-list li {
  padding: 8px 10px;
  cursor: pointer;
  font-size: 0.9em;
  border-bottom: 1px solid #f3f3f3;
}
.ew-picker-list li:hover { background: #f0f0f0; }
.ew-picker-empty { color: #999; cursor: default; }
.ew-picker-empty:hover { background: #fff; }

/* Read-only worksite fields (when an address is chosen from the list) */
.ew-readonly,
.ew-modal-body input[readonly] {
  background: #f0f0f0;
  cursor: not-allowed;
}
.ew-checkbox { margin: 2px 0 4px; }
.ew-checkbox label { font-weight: normal; cursor: pointer; }
.ew-checkbox-row { display: flex; gap: 24px; margin: 2px 0 6px; }
.ew-checkbox-row .ew-checkbox { margin: 0; }

sp_widget.script:
(function() {

  data.employees    = [];
  data.supervisor   = '';
  data.error        = '';
  data.actionResult = null;
  data.hidden       = false;

  // ── 0. Supervisory status access check ────────────────────
  var ALLOWED_STATUSES = [
    '74bb71501b1231104da26311f54bcb95',
    'f8bb71501b1231104da26311f54bcb95',
		'38bb71501b1231104da26311f54bcb95'
  ];
  var currentUserGr = new GlideRecord('sys_user');
  if (currentUserGr.get(gs.getUserID())) {
    var userStatus = currentUserGr.getValue('u_supervisory_status') || '';
    if (ALLOWED_STATUSES.indexOf(userStatus) === -1) {
      data.hidden = true;
      return;
    }
  } else {
    data.hidden = true;
    return;
  }

  // ── 1. Determine which supervisor to show ──────────────────
  var supervisorSysId = options.supervisor_sys_id || $sp.getParameter('supervisor_sys_id') || gs.getUserID();

  // ── 2. Handle any client action BEFORE re-rendering the list ─
  if (input && input.action) {
    handleAction(input);
  }

  if (!supervisorSysId) {
    data.error = 'No supervisor specified.';
    return;
  }

  // ── 3. Resolve supervisor display name ─────────────────────
  var supGr = new GlideRecord('sys_user');
  if (supGr.get(supervisorSysId)) {
    data.supervisor = supGr.getDisplayValue('name');
  } else {
    data.error = 'Supervisor not found.';
    return;
  }

  // ── 4. Query direct reports ────────────────────────────────
  var empGr = new GlideRecord('sys_user');
  empGr.addActiveQuery();
  empGr.addQuery('u_fpps_supervisor', supervisorSysId);
  empGr.orderBy('last_name');
  empGr.orderBy('first_name');
  empGr.query();

  while (empGr.next()) {
    data.employees.push(buildEmp(empGr));
  }

  // ── 5. Worksite address list (cmn_location, type employee_worksite) ─
  data.locations = [];
  var locGr = new GlideRecord('cmn_location');
  locGr.addQuery('cmn_location_type', 'employee_worksite');
  locGr.orderBy('city');
  locGr.orderBy('u_employee_worksite_street_1');
  locGr.query();
  while (locGr.next()) {
    data.locations.push(buildLoc(locGr));
  }

  // ── Helpers ────────────────────────────────────────────────

  function buildEmp(gr) {
    var cubicle = gr.getValue('u_employee_worksite_cubicle')  || '';
    var floor   = gr.getValue('u_employee_worksite_floor')    || '';
    var remote  = gr.getValue('u_employee_worksite_remote') === 'true' || gr.getValue('u_employee_worksite_remote') === true || gr.getValue('u_employee_worksite_remote') == 1;
    var street1 = gr.getValue('u_employee_worksite_street_1') || '';
    var street2 = gr.getValue('u_employee_worksite_street_2') || '';
    var city    = gr.getValue('u_employee_worksite_city')     || '';
    var state   = gr.getValue('u_employee_worksite_state')    || '';
    var zip     = gr.getValue('u_employee_worksite_zip')      || '';

    var locationId    = gr.getValue('u_employee_worksite_address') || '';
    var locationLabel = '';
    var manual        = false;

    if (locationId) {
      var lgr = new GlideRecord('cmn_location');
      if (lgr.get(locationId)) {
        street1 = lgr.getValue('u_employee_worksite_street_1') || '';
        street2 = lgr.getValue('u_employee_worksite_street_2') || '';
        city    = lgr.getValue('city')  || '';
        state   = lgr.getValue('state') || '';
        zip     = lgr.getValue('zip')   || '';
        locationLabel = locLabel(street1, street2, city, state, zip);
      } else {
        locationId = '';
      }
    }

    if (!locationId) {
      manual = !remote && !!(street1 || street2 || city || state || zip);
    }

    var line1 = [street1, street2].filter(function(s){ return s; }).join(', ');
    var line2 = [city, state].filter(function(s){ return s; }).join(', ');
    if (zip) line2 += (line2 ? ' ' : '') + zip;
    var display = [line1, line2].filter(function(s){ return s; }).join(', ');

    var locParts = [];
    if (cubicle) locParts.push('Cubicle/Office ' + cubicle);
    if (floor)   locParts.push('Floor ' + floor);
    var locLine = locParts.join(' \u2022 ');

    return {
      sys_id           : gr.getUniqueValue(),
      name             : gr.getDisplayValue('name'),
      employee_number  : gr.getValue('employee_number') || '',
      title            : gr.getDisplayValue('title')      || '',
      department       : gr.getDisplayValue('department') || '',
      email            : gr.getValue('email')             || '',
      phone            : gr.getValue('phone')             || '',
      location         : locationId,
      location_label   : locationLabel,
      manual           : manual,
      remote           : remote,
      cubicle          : cubicle,
      floor            : floor,
      street_1         : street1,
      street_2         : street2,
      city             : city,
      state            : state,
      zip              : zip,
      loc_line         : locLine,
      worksite_display : display,
      worksite         : display
    };
  }

  function buildLoc(gr) {
    var s1 = gr.getValue('u_employee_worksite_street_1') || '';
    var s2 = gr.getValue('u_employee_worksite_street_2') || '';
    var ci = gr.getValue('city')  || '';
    var st = gr.getValue('state') || '';
    var zp = gr.getValue('zip')   || '';
    return {
      sys_id   : gr.getUniqueValue(),
      street_1 : s1,
      street_2 : s2,
      city     : ci,
      state    : st,
      zip      : zp,
      label    : locLabel(s1, s2, ci, st, zp)
    };
  }

  function locLabel(s1, s2, ci, st, zp) {
    var seg = [];
    if (s1) seg.push(s1);
    if (s2) seg.push(s2);
    if (ci) seg.push(ci);
    var tail = [st, zp].filter(function(x){ return x; }).join(' ');
    if (tail) seg.push(tail);
    return seg.join(', ');
  }

  function applyWorksite(gr, src) {
    gr.setValue('u_employee_worksite_cubicle', src.cubicle || '');
    gr.setValue('u_employee_worksite_floor',   src.floor   || '');
    gr.setValue('u_employee_worksite_remote',  src.remote ? 'true' : 'false');

    if (src.remote) {
      gr.setValue('u_employee_worksite_address',  '');
      gr.setValue('u_employee_worksite_street_1', 'Remote');
      gr.setValue('u_employee_worksite_street_2', '');
      gr.setValue('u_employee_worksite_city',     src.city  || '');
      gr.setValue('u_employee_worksite_state',    src.state || '');
      gr.setValue('u_employee_worksite_zip',      src.zip   || '');
      return true;
    }

    if (src.manual || !src.location) {
      gr.setValue('u_employee_worksite_address',  '');
      gr.setValue('u_employee_worksite_street_1', src.street_1 || '');
      gr.setValue('u_employee_worksite_street_2', src.street_2 || '');
      gr.setValue('u_employee_worksite_city',     src.city     || '');
      gr.setValue('u_employee_worksite_state',    src.state    || '');
      gr.setValue('u_employee_worksite_zip',      src.zip      || '');
      return true;
    }

    var lgr = new GlideRecord('cmn_location');
    if (!lgr.get(src.location)) return false;
    gr.setValue('u_employee_worksite_address',  src.location);
    gr.setValue('u_employee_worksite_street_1', lgr.getValue('u_employee_worksite_street_1') || '');
    gr.setValue('u_employee_worksite_street_2', lgr.getValue('u_employee_worksite_street_2') || '');
    gr.setValue('u_employee_worksite_city',     lgr.getValue('city')  || '');
    gr.setValue('u_employee_worksite_state',    lgr.getValue('state') || '');
    gr.setValue('u_employee_worksite_zip',      lgr.getValue('zip')   || '');
    return true;
  }

  function validateAddress(src) {
    if (src.remote) {
      if (!src.city || !src.state || !src.zip) {
        return 'In Remote mode, City, State, and ZIP are required.';
      }
      return '';
    }
    if (src.manual) {
      if (!src.street_1 || !src.city || !src.state || !src.zip) {
        return 'Street 1, City, State, and ZIP are required.';
      }
      return '';
    }
    if (!src.location) {
      return 'An address selection is required.';
    }
    return '';
  }

  function handleAction(inp) {
    var act = inp.action;

    if (act === 'updateWorksite' && inp.emp && inp.emp.sys_id) {
      var vmsgU = validateAddress(inp.emp);
      if (vmsgU) {
        data.actionResult = { ok: false, type: 'update', message: vmsgU };
        return;
      }
      var ugr = new GlideRecord('sys_user');
      if (ugr.get(inp.emp.sys_id)) {
        if (!applyWorksite(ugr, inp.emp)) {
          data.actionResult = { ok: false, type: 'update', message: 'Selected address could not be found.' };
          return;
        }
        ugr.update();
        data.actionResult = { ok: true, type: 'update', name: ugr.getDisplayValue('name') };
      } else {
        data.actionResult = { ok: false, type: 'update', message: 'User not found.' };
      }
      return;
    }

    if (act === 'remove' && inp.sys_id) {
      var rgr = new GlideRecord('sys_user');
      if (!rgr.get(inp.sys_id)) {
        data.actionResult = { ok: false, type: 'remove', message: 'User not found.' };
        return;
      }
      var removeName = rgr.getDisplayValue('name');
      rgr.setValue('u_fpps_supervisor', '');
      rgr.update();
      data.actionResult = { ok: true, type: 'remove', name: removeName };
      return;
    }

    if (act === 'addEmployee' && inp.emp && inp.emp.sys_id) {
      var vmsgA = validateAddress(inp.emp);
      if (vmsgA) {
        data.actionResult = { ok: false, type: 'add', message: vmsgA };
        return;
      }
      var agr = new GlideRecord('sys_user');
      if (!agr.get(inp.emp.sys_id)) {
        data.actionResult = { ok: false, type: 'add', message: 'User not found.' };
        return;
      }
      if (!applyWorksite(agr, inp.emp)) {
        data.actionResult = { ok: false, type: 'add', message: 'Selected address could not be found.' };
        return;
      }
      agr.setValue('u_fpps_supervisor', supervisorSysId);
      agr.update();
      var addName = agr.getDisplayValue('name');
      data.actionResult = { ok: true, type: 'add', name: addName };
      return;
    }
  }

})();

