(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
	data.supervisor = '';
data.cubicle = '';
data.floor = '';
data.addressLines = [];

var userGR = new GlideRecord('sys_user');
userGR.get(gs.getUserID());

data.supervisor = userGR.getDisplayValue('u_fpps_supervisor');
data.cubicle    = userGR.getValue('u_employee_worksite_cubicle') || '';
data.floor      = userGR.getValue('u_employee_worksite_floor')   || '';

var street1 = userGR.getValue('u_employee_worksite_street_1') || '';
var street2 = userGR.getValue('u_employee_worksite_street_2') || '';
var city    = userGR.getValue('u_employee_worksite_city')     || '';
var state   = userGR.getValue('u_employee_worksite_state')    || '';
var zip     = userGR.getValue('u_employee_worksite_zip')      || '';

if (street1) data.addressLines.push(street1);
if (street2) data.addressLines.push(street2);

var cityStateZip = '';
if (city && state) cityStateZip = city + ', ' + state;
else if (city)     cityStateZip = city;
else if (state)    cityStateZip = state;
if (zip)           cityStateZip += (cityStateZip ? ' ' : '') + zip;
if (cityStateZip)  data.addressLines.push(cityStateZip);

})();

