sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var userGR = new GlideRecord('sys_user');
    userGR.addQuery('u_fpps_supervisor', current.getValue('u_fpps_supervisor'));
    userGR.addQuery('u_employee_worksite_verification_required', true);
    userGR.query();
    if (userGR.getRowCount() == 0) {
        var taskGR = new GlideRecord('sn_hr_core_task');
        taskGR.addActiveQuery();
        taskGR.addQuery('template', '72c69a948792c7104567c8460cbb35ae');
        taskGR.addQuery('assigned_to', current.getValue('u_fpps_supervisor'));
        taskGR.query();
        if (taskGR.next()) {
            taskGR.setValue('state', '3');
            taskGR.work_notes = 'This task was closed by the system because all employees have been verified.'
            taskGR.update();
        }
    }




})(current, previous);

(function executeRule(current, previous /*null when async*/) {

	current.setValue('u_employee_worksite_no_direct_reports_last_verified', new GlideDateTime());

})(current, previous);

(function executeRule(current, previous /*null when async*/ ) {
	//updates the user's direct reports 
    var userGR = new GlideRecord('sys_user');
    userGR.addQuery('u_fpps_supervisor_eci', current.getValue('u_eci'));
    userGR.query();
    while (userGR.next()) {
        userGR.setValue('u_fpps_supervisor', current.getUniqueValue());
        userGR.setWorkflow('false');
        userGR.update();
		gs.addInfoMessage('Updated FPPS Supervisor for ' + userGR.getDisplayValue());
    }

})(current, previous);

(function executeRule(current, previous /*null when async*/) {

	current.setValue('u_employee_worksite_last_update', new GlideDateTime());
	current.setValue('u_employee_worksite_last_verified', '');
	current.setValue('u_employee_worksite_last_verified_by', '');

})(current, previous);

(function executeRule(current, previous /*null when async*/) {

	if(!current.getValue('u_fpps_supervisor')){
		current.setValue('u_fpps_supervisor_eci','');
	}
	else if (current.getValue('u_fpps_supervisor')){
		var supECI = current.u_fpps_supervisor.u_eci.getDisplayValue();
		if(supECI){
			current.setValue('u_fpps_supervisor_eci',supECI);
		}

	}

})(current, previous);

(function executeRule(current, previous /*null when async*/) {

	current.setValue('u_fpps_supervisor_last_update', new GlideDateTime());


})(current, previous);

(function executeRule(current, previous /*null when async*/ ) {

    var previousSupervisor = previous.getValue('u_fpps_supervisor');
    var currentSupervisor = current.getValue('u_fpps_supervisor');

    function countDirectReports(supervisorID) {
        var ga = new GlideAggregate('sys_user');
        ga.addQuery('u_fpps_supervisor', supervisorID);
        ga.addActiveQuery();
        ga.addAggregate('COUNT');
        ga.query();
        if (ga.next()) {
            return parseInt(ga.getAggregate('COUNT'), 10) || 0;
        }
        return 0;
    }

    function updateSupervisorCount(supervisorID, clearVerificationFlag) {
        var gr = new GlideRecord('sys_user');
        if (!gr.get(supervisorID)) {
            return;
        }
        gr.setValue('u_employee_worksite_number_of_direct_reports', countDirectReports(supervisorID));
        if (clearVerificationFlag) {
            gr.setValue('u_employee_worksite_no_direct_reports_verification_required', false);
        }
        gr.update();
    }

    if (previousSupervisor && previousSupervisor != currentSupervisor) {
        updateSupervisorCount(previousSupervisor, false);
    }

    if (currentSupervisor) {
        updateSupervisorCount(currentSupervisor, true);
    }

})(current, previous);

(function executeRule(current, previous /*null when async*/ ) {

        var taskGR = new GlideRecord('sn_hr_core_task');
        taskGR.addActiveQuery();
        taskGR.addQuery('template', '72c69a948792c7104567c8460cbb35ae');
        taskGR.addQuery('assigned_to', current.getUniqueValue());
        taskGR.query();
        if (taskGR.next()) {
            taskGR.setValue('state', '3');
            taskGR.work_notes = 'This task was closed by the system because the supervisor verified they do not have direct reports.';
            taskGR.update();
        }




})(current, previous);

(function executeRule(current, previous /*null when async*/) {

	current.setValue('u_employee_worksite_address_last_update', new GlideDateTime());


})(current, previous);

sys_script_include.script:
var EmployeeWorksiteUtils = Class.create();
EmployeeWorksiteUtils.prototype = {
    initialize: function() {},
    getSupervisorsWithStatus: function(encodedQuery) {
        //gets active users with supervisory status of 2, 4 or 5
        var supsArr = [];
        var supGR = new GlideRecord("sys_user");
        supGR.addEncodedQuery("usr_active=true^u_supervisory_status=74bb71501b1231104da26311f54bcb95^ORu_supervisory_status=f8bb71501b1231104da26311f54bcb95^ORu_supervisory_status=38bb71501b1231104da26311f54bcb95"); //sup status 2,4,5
        if (encodedQuery) {
            supGR.addEncodedQuery(encodedQuery);
        }
        supGR.query();
        while (supGR.next()) {
            supsArr.push(supGR.getUniqueValue());
        }
        var uniqueSupervisorsCleaned = this._removeExclusions(supsArr);

        return uniqueSupervisorsCleaned;
    },
    getSupervisorsWithEmployees: function(encodedQuery) {
        //gets the supervisors that currently have employees under them
        var ga = new GlideAggregate('sys_user');
        ga.addNotNullQuery('u_fpps_supervisor');
        if (encodedQuery) {
            ga.addEncodedQuery(encodedQuery);
        }
        //ga.setLimit(30);
        ga.groupBy('u_fpps_supervisor');
        ga.query();

        var uniqueSupervisors = [];

        while (ga.next()) {
            var sysId = ga.getValue('u_fpps_supervisor'); // raw sys_id of referenced record

            uniqueSupervisors.push(sysId);
        }
        return uniqueSupervisors;
    },
    getSupervisorsWithTasks: function(encodedQuery, templateSysId) {

        //gets the supervisors that have had verification tasks assigned to them in the last 30 days
        var ga = new GlideAggregate('sn_hr_core_task');
        ga.addNotNullQuery('assigned_to');
        ga.addEncodedQuery('template=' + templateSysId);
        if (encodedQuery) {
            ga.addEncodedQuery(encodedQuery);
        }

        ga.groupBy('assigned_to');
        ga.query();

        var uniqueSupervisorsWithTasks = [];

        while (ga.next()) {
            var sysId = ga.getValue('assigned_to');

            uniqueSupervisorsWithTasks.push(sysId);
        }
        return uniqueSupervisorsWithTasks;

    },
    getSupervisorsForVerificationTasks: function(encodedQuery, maxCount,countOnly) {

        if (!maxCount) {
            maxCount = 1000000; //it will never be higher than 1 million
        }
        var supsWithEmps = this.getSupervisorsWithStatus(encodedQuery);
        var supsWithTasks = this.getSupervisorsWithTasks('opened_atRELATIVEGT@dayofweek@ago@30', '72c69a948792c7104567c8460cbb35ae');
        var arrayUtil = new ArrayUtil();
        var allSups =  arrayUtil.diff(supsWithEmps, supsWithTasks);

        if (countOnly) {
            return allSups.length;
        } else {
            return allSups.slice(0, maxCount);
        }
    },

    getEmployeesMissingData: function(supervisorSysId) {
        var supObj = {};
        supObj.employees = [];
        var empGR = new GlideRecord('sys_user');
        empGR.addEncodedQuery('active=true^u_employee_worksite_street_1ISEMPTY^ORu_employee_worksite_cityISEMPTY^ORu_employee_worksite_stateISEMPTY^ORu_employee_worksite_zipISEMPTY');
        empGR.addQuery('u_fpps_supervisor', supervisorSysId);
        empGR.query();
        while (empGR.next()) {
            var employee = {};
            employee.sys_id = empGR.getUniqueValue();
            employee.name = empGR.u_full_name.getDisplayValue();
            employee.email = empGR.email.getDisplayValue();
            employee.supervisor = empGR.u_fpps_supervisor.sys_id.getDisplayValue();
            employee.emptyFields = this._getEmptyFields(empGR);
            employee.description = this._createEmployeeDescription(employee);
            var supervisor = empGR.u_fpps_supervisor.sys_id.getDisplayValue();
            supObj.employees.push(employee);

        }
        return supObj;

    },
    getSupervisorsForFillTasks: function(encodedQuery, maxCount, countOnly) {
        if (!maxCount) {
            maxCount = 1000000; //it will never be higher than 1 million
        }
        var supsWithEmpsMissingData = this.getSupervisorsWithEmployeesMissingData(encodedQuery);
        var supsWithTasks = this.getSupervisorsWithTasks('active=true', '9b60e45d1beacb500a8a5355604bcb91');
        var arrayUtil = new ArrayUtil();
        var allSups = arrayUtil.diff(supsWithEmpsMissingData, supsWithTasks);
        if (countOnly) {
            return allSups.length;
        } else {
            return allSups.slice(0, maxCount);
        }
    },
    getSupervisorsWithEmployeesMissingData: function(encodedQuery) {
        //gets the supervisors that currently have employees under them
        var ga = new GlideAggregate('sys_user');
        ga.addEncodedQuery('active=true^u_employee_worksite_street_1ISEMPTY^ORu_employee_worksite_cityISEMPTY^ORu_employee_worksite_stateISEMPTY^ORu_employee_worksite_zipISEMPTY^u_fpps_supervisorISNOTEMPTY');




        if (encodedQuery) {
            ga.addEncodedQuery(encodedQuery);
        }

        ga.groupBy('u_fpps_supervisor');
        ga.query();

        var uniqueSupervisors = [];

        while (ga.next()) {
            var sysId = ga.getValue('u_fpps_supervisor'); // raw sys_id of referenced record

            uniqueSupervisors.push(sysId);
        }
        var uniqueSupervisorsCleaned = this._removeExclusions(uniqueSupervisors);

        return uniqueSupervisorsCleaned;
    },
    _getExclusionList: function() {
        //gets the secretary and their direct reports
        var exclusion_list = [];
        var id = 'b2b5117f9785b29015b1f2aad053aff3'; //secretary
        supGR = new GlideRecord('sys_user');
        supGR.addEncodedQuery('sys_id=' + id + '^ORu_fpps_supervisor=' + id);
        supGR.query();
        while (supGR.next()) {
            exclusion_list.push(supGR.getUniqueValue());
        }
        return exclusion_list;
    },
    _removeExclusions: function(arrayToRemoveFrom) {
        var exclusionList = this._getExclusionList();
        var supervisorsClean = arrayToRemoveFrom.filter(function(sysId) {
            return exclusionList.indexOf(sysId) === -1;
        });
        return supervisorsClean;
    },
    _getEmptyFields: function(userGR) {
        var emptyFields = [];
        var fields = ['u_employee_worksite_street_1', 'u_employee_worksite_city', 'u_employee_worksite_state', 'u_employee_worksite_zip'];

        for (var i in fields) {
            if ((!userGR.getValue(fields[i])) || (userGR.getValue(fields[i]) == 'NO DATA AVAILABLE')) {
                emptyFields.push(userGR[fields[i]].getLabel())
            }
        }
        return emptyFields;
    },
    getRichDescriptionForFillTask: function(supervisorSysId) {
        var supObj = this.getEmployeesMissingData(supervisorSysId);
        var desc = `<div><div><span style="font-size: 12pt;">Please complete the worksite information for the employees below by using the My Direct Reports widget on <a href="https://hr.doi.gov" target="_blank" rel="noopener">https://hr.doi.gov</a></span></div><div>&nbsp;</div><div><span style="font-size: 12pt;">Employees missing worksite information (Employee name : Fields missing data)</span></div><div>`;
        desc += `<ul style="list-style-position: inside;">`
        for (var i in supObj['employees']) {
            desc += `<li>${supObj['employees'][i]['description']}</li>`
        }
        desc += `</ul>`;
        desc += `</div></div>`;
        return desc;


    },
    _createEmployeeDescription: function(employeeObj) {
        var fields = employeeObj.emptyFields.join(",");
        var desc = `<span style="font-size: 12pt;">${employeeObj.name} : ${fields} </span>`;
        return desc;
    },

    type: 'EmployeeWorksiteUtils'
};

